code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    # Horizontal colored bands: infer a vertical period from the stripe sequence.
    full_rows = {}
    for r, row in enumerate(grid):
        if row and row[0] != 0 and all(v == row[0] for v in row):
            full_rows[r] = row[0]
    if full_rows:
        inds = sorted(full_rows)
        if inds == list(range(inds[0], inds[-1] + 1)):
            period = len(inds)
        else:
            repeats = [j-i for i in inds for j in inds if j > i and full_rows[i] == full_rows[j]]
            period = min(repeats) if repeats else (inds[-1] - inds[0] + 1)
        residues = {}
        for r, color in full_rows.items():
            residues[r % period] = color
        return [[residues.get(r % period, 0) for _ in range(w)] for r in range(h)]

    # Colored anti-diagonal traces encode the repeating color by (r+c) modulo period.
    bands = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                k = r + c
                if k in bands and bands[k] != color:
                    return [list(row) for row in grid]
                bands[k] = color
    if bands:
        period = None
        for p in range(1, max(h, w) + 1):
            residues = {}
            ok = True
            for k, color in bands.items():
                q = k % p
                if q in residues and residues[q] != color:
                    ok = False
                    break
                residues[q] = color
            if ok and len(residues) == p:
                period = p
                break
        if period is None:
            period = max(bands) - min(bands) + 1
            residues = {k % period: v for k, v in bands.items()}
        return [[residues[(r+c) % period] for c in range(w)] for r in range(h)]
    return [list(row) for row in grid]
'''
p.write_text(code)
print(p, p.read_text())

